import pathlib,json,sys,shutil,hashlib,datetime
batch,slug,reason=sys.argv[1:4];base=pathlib.Path(f'data/artwork-generated/batch-{batch}');r=json.loads((base/f'{slug}.json').read_text());rej=base/'rejected';rej.mkdir(exist_ok=True);n=len(list(rej.glob(f'{slug}-attempt-*.png')))+1;p=rej/f'{slug}-attempt-{n:02}.png';shutil.copy2(r['original_file'],p);j=p.with_suffix('.json');d={'original_file':str(p),'native_sha256':r['native_sha256'],'prompt':r['prompt'],'reason':reason,'generated_file':r['generated_file'],'rejected_at':datetime.datetime.now(datetime.timezone.utc).isoformat()};j.write_text(json.dumps(d,indent=2)+'\n');draft=base/'drafts/session100-C';(draft/f'{slug}-rejected-history.json').write_text(json.dumps(r.get('rejected_attempts',[])+[{'original_file':str(p),'receipt_file':str(j),'native_sha256':r['native_sha256'],'reason':reason}],indent=2)+'\n');r['status']='needs-own-retry';r['reason']=reason;(base/f'{slug}.json').write_text(json.dumps(r,indent=2)+'\n');print(p)
